UPDATE tools SET faq = $x$[{"q": "What is Beautiful.ai used for?", "a": "Beautiful.ai is an AI presentation tool where slides auto-format as you add content. It's designed for individuals who create business presentations and want professional-looking results without manual design work."}, {"q": "Is Beautiful.ai free?", "a": "No. Beautiful.ai has no permanent free plan. It offers a 14-day free trial of Pro or Team (credit card required), and students get one year free with a .edu email. Pro costs $14.50/month billed annually, and Team costs $40/user/month billed annually or $50/user/month billed monthly."}, {"q": "Which is better for investor pitches — Beautiful.ai or Pitch?", "a": "Beautiful.ai's Team plan includes slide and viewer analytics, but a verified, sourced comparison of its investor-pitch features against Pitch's is not available from primary sources."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'en';

