UPDATE tools SET faq = $x$[{"q": "Що таке Krea AI?", "a": "Krea AI — це AI-платформа для творчості, яка включає генерацію зображень у реальному часі (зображення оновлюється під час набору тексту), AI-полотно для редагування та покращення зображень, генерацію відео та AI-навчання на власних зображеннях користувача."}, {"q": "Чи є Krea AI безкоштовною?", "a": "Krea AI має безкоштовний план із 100 обчислювальними одиницями на день і без потреби в кредитній картці. План Pro коштує $35/місяць ($21/місяць при річній оплаті), а план Max коштує $105/місяць ($63/місяць при річній оплаті) — за більшу кількість одиниць, швидшу обробку та вищу одночасну пропускну здатність."}, {"q": "Чи може Krea AI генерувати відео?", "a": "Так. Krea AI має можливості генерації відео — текст-у-відео та зображення-у-відео. Якість конкурентна порівняно з іншими інструментами середнього рівня, але загалом нижча за Runway чи Kling для професійного відеовиробництва."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'ua';

