 WHERE slug = 'deepl' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Can DeepL improve my English writing?", "a": "DeepL Write is a separate tool from DeepL Translate that rephrases sentences to improve clarity and style. It is less comprehensive than Grammarly for grammar checking but strong for rephrasing."}, {"q": "Is DeepL free?", "a": "DeepL offers a free plan with 50,000 characters per month and one file translation per month (up to 5MB). Paid Individual, Team, and Business plans raise those limits, with Business offering unlimited characters; exact pricing varies by billing region and is shown on DeepL's pricing page."}, {"q": "Which is more accurate — DeepL or Google Translate?", "a": "DeepL is often rated higher for naturalness in translation quality, particularly for European languages. DeepL now states it covers 100+ languages, similar in scope to Google Translate's coverage."}]$x$::jsonb
