 WHERE slug = 'lindy' AND lang = 'en';

UPDATE tools SET choose_if = $x$["You want an AI teammate that connects to 1,000+ apps and MCP servers", "You need computer use or model selection and are comfortable with Team-tier credit pricing", "You are replacing or augmenting manual assistant work and per-user credit pricing is acceptable", "Your organization needs enterprise controls like SSO, SCIM, HIPAA or audit logs", "You want to trial an agent platform for a week without entering a credit card"]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Lindy AI?", "a": "Lindy is an AI assistant platform that builds personal and business AI agents. Agents can handle email management, meeting preparation, CRM updates, research, and customer support. You connect Lindy to your apps (Gmail, Slack, Salesforce) and define workflows for it to execute."}, {"q": "Is Lindy AI free?", "a": "There is no ongoing free plan. Lindy offers a 7-day free trial with $50 in credits and no credit card required. After that, the Team plan is billed per active user per month, starting at $29.99 for 3,000 credits (5,000 credits costs $49.99/month)."}, {"q": "What is the difference between Lindy and Zapier?", "a": "Zapier automates fixed, rule-based workflows between apps. Lindy uses AI to handle variable situations — reading emails, making decisions, responding contextually. Zapier is better for predictable automation; Lindy is better when tasks require judgment and natural language."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'en';

