UPDATE tools SET faq = $x$[{"q": "Was ist Lindy AI?", "a": "Lindy ist eine KI-Assistenzplattform, die persönliche und geschäftliche KI-Agenten erstellt. Agenten können E-Mail-Verwaltung, Besprechungsvorbereitung, CRM-Aktualisierungen, Recherche und Kundensupport übernehmen. Sie verbinden Lindy mit Ihren Apps (Gmail, Slack, Salesforce) und definieren Workflows, die es ausführen soll."}, {"q": "Ist Lindy AI kostenlos?", "a": "Es gibt keinen dauerhaften kostenlosen Plan. Lindy bietet einen 7-tägigen kostenlosen Test mit 50 $ an Credits ohne erforderliche Kreditkarte. Danach wird der Team-Plan pro aktivem Nutzer und Monat abgerechnet, beginnend bei 29,99 $ für 3.000 Credits (5.000 Credits kosten 49,99 $/Monat)."}, {"q": "Was ist der Unterschied zwischen Lindy und Zapier?", "a": "Zapier automatisiert feste, regelbasierte Workflows zwischen Apps. Lindy nutzt KI, um variable Situationen zu bewältigen – E-Mails lesen, Entscheidungen treffen, kontextbezogen antworten. Zapier eignet sich besser für vorhersehbare Automatisierung; Lindy ist besser geeignet, wenn Aufgaben Urteilsvermögen und natürliche Sprache erfordern."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'de';

