 WHERE slug = 'clearscope' AND lang = 'en';

UPDATE tools SET choose_if = $x$["You publish content regularly and want to track how it appears in ChatGPT, Gemini and Claude answers", "You need to brief writers with clear, term-level optimization reports", "You have a team and want unlimited seats without per-user fees", "You are investing in answer engine optimization, not just traditional Google rankings"]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is the difference between Clearscope and SurferSEO?", "a": "Both are AI content optimization tools but with different strengths. Clearscope excels at content grading and topic depth analysis. SurferSEO offers a more complete platform with a real-time content editor, keyword research, and AI writing. Clearscope is deeper for content quality; Surfer is broader as an all-in-one tool."}, {"q": "Does Clearscope have AI writing?", "a": "Yes. Clearscope's Draft with AI feature turns a content optimization report into a first draft, and paid plans include a monthly allowance of AI drafts (20 per month on the Essentials and Business tiers)."}, {"q": "How much does Clearscope cost?", "a": "Clearscope's Essentials plan starts at $129 per month, Business is $399 per month, and Enterprise uses custom pricing. All tiers include unlimited users and projects, and there is a 14-day free trial but no free tier."}]$x$::jsonb
