UPDATE tools SET faq = $x$[{"q": "What is Mistral Le Chat?", "a": "Mistral Le Chat is now called Vibe. It is Mistral AI's consumer AI assistant, available at chat.mistral.ai, and runs on Mistral's own models, currently built around Mistral Medium 3.5. Mistral is a French AI company emphasizing European data sovereignty and open-weight model development."}, {"q": "Is Le Chat free?", "a": "The product is now called Vibe. It has a free plan with limited messages, web searches, coding sessions, image generation and $10/month in API credits. The Pro plan is $14.99/month for more messages, all-day coding, image generation and included API credits."}, {"q": "Are Mistral models open source?", "a": "Mistral releases several models as open weights, including Mistral Large, Medium 3.5, Small and Ministral, under open licenses such as Apache 2.0 or a modified MIT license, that developers can download and run themselves. Vibe is Mistral's hosted consumer product built on top of these models."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'en';

