UPDATE tools SET faq = $x$[{"q": "Was ist Pika AI?", "a": "Pika ist eine webbasierte Plattform zur Erstellung kurzer KI-Videos, -Bilder und -Audioinhalte aus Text- oder Bild-Prompts. Sie kombiniert ihr eigenes Pika 2.5-Videomodell mit Modellen von Drittanbietern wie Google und ElevenLabs und bietet eine Entwickler-API für individuelle Workflows."}, {"q": "Ist Pika kostenlos?", "a": "Nein. Kostenlose Konten erhalten 0 monatliche Credits und müssen Credit-Pakete kaufen, um Inhalte zu generieren. Die kostenpflichtigen Pläne beginnen mit Starter für 10 $/Monat bei monatlicher Abrechnung oder 8 $/Monat bei jährlicher Abrechnung, gefolgt von Creator für 35 $/Monat bei monatlicher Abrechnung oder 28 $/Monat bei jährlicher Abrechnung, und Fancy ab 95 $/Monat bei monatlicher Abrechnung oder 76 $/Monat bei jährlicher Abrechnung."}, {"q": "Was ist der Unterschied zwischen Pika und Kling?", "a": "Pikas Plattform kombiniert mehrere Video-Drittmodelle, darunter eines von Google, neben dem eigenen Pika 2.5-Modell, während Kling ein eigenständiger Videogenerierungsdienst mit nur einem Modell ist. Dieser Multi-Modell-Ansatz ist der Hauptunterschied zwischen beiden."}]$x$::jsonb
 WHERE slug = 'pika' AND lang = 'de';

