 WHERE slug = 'semrush' AND lang = 'en';

UPDATE tools SET choose_if = $x$["You need to track brand visibility in AI answers, not just Google rankings", "You run an agency or in-house team managing multiple domains", "You want keyword, backlink and competitor data in a single platform", "You can justify a higher monthly spend for depth of data", "You want to combine classic SEO audits with new AI-search monitoring"]$x$::jsonb
 WHERE slug = 'semrush' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Is SEMrush worth the price?", "a": "For serious SEO professionals and agencies, SEMrush is generally considered worth its $139-$549/month price on monthly billing (about $117-$456/month if paid annually). It replaces multiple standalone tools (keyword research, backlink checker, site audit, rank tracking). For small businesses doing basic SEO, cheaper alternatives like Ubersuggest may suffice."}, {"q": "Can Frase replace SEMrush?", "a": "No. Frase focuses on content optimization — it doesn't do full keyword research, backlink analysis, or technical SEO audits the way SEMrush does. Frase is often used alongside SEMrush: SEMrush for strategy and keyword research, Frase for content creation and optimization."}]$x$::jsonb
 WHERE slug = 'semrush' AND lang = 'en';

