UPDATE tools SET faq = $x$[{"a": "Duolingo Max — это премиальный уровень Duolingo, добавляющий функции на базе ИИ, изначально созданные на основе GPT-4 от OpenAI. Его ключевые возможности — Video Call, живой устный разговор с анимированным персонажем по имени Lily, который запоминает детали из предыдущих сессий, и Roleplay, практические разговоры с ИИ-персонажами в реалистичных жизненных сценариях. Обратите внимание, что 'Explain My Answer' больше не является эксклюзивом Max и теперь бесплатна для всех пользователей Duolingo.", "q": "Что такое Duolingo Max?"}, {"a": "Duolingo эффективно формирует словарный запас и базовую грамматику, но, как правило, его недостаточно для достижения свободного владения языком самостоятельно. Лучше всего он работает как ежедневная привычка в сочетании с другой практикой — общением с носителями языка, просмотром контента или использованием таких инструментов, как iTalki, для практики разговорной речи.", "q": "Может ли Duolingo научить меня говорить свободно?"}]$x$::jsonb
