 WHERE slug = 'prezi' AND lang = 'en';

UPDATE tools SET cons = ARRAY[$x$Pricing is served through a JavaScript-only page, so plan costs and free-tier limits can't be confirmed without the live site$x$, $x$No formal version numbers make it hard to track exactly what changed and when$x$, $x$The signature zooming canvas can feel gimmicky and clashes with conventional corporate templates$x$, $x$Swoop is a separate product from Prezi's core app, splitting the AI deck workflow across two tools$x$, $x$Swoop's own pricing runs on a credits model that was also not independently verified$x$]::text[]
 WHERE slug = 'prezi' AND lang = 'en';

